/** Lower-cased name -> entry, built once on first use. */
let _index: Map<string, BulkMedicine> | null = null;

function index(): Map<string, BulkMedicine> {
  if (_index) return _index;
  _index = new Map();
  for (const m of BULK_MEDICINES) _index.set(m.n.toLowerCase(), m);
  return _index;
}

/** Exact (case-insensitive) lookup. */
export function findBulkMedicine(query: string): BulkMedicine | null {
  const q = (query || "").trim().toLowerCase();
  if (q.length < 3) return null;
  return index().get(q) || null;
}

/**
 * Prefix search for autocomplete.
 *
 * Results are pre-sorted by openFDA label count, so the most commonly
 * dispensed medicines surface first rather than alphabetically.
 */
export function searchBulkMedicines(query: string, limit = 10): BulkMedicine[] {
  const q = (query || "").trim().toLowerCase();
  if (q.length < 2) return [];
  const out: BulkMedicine[] = [];
  for (const m of BULK_MEDICINES) {
    const n = m.n.toLowerCase();
    if (n === q || n.startsWith(q)) {
      out.push(m);
      if (out.length >= limit) break;
    }
  }
  if (out.length < limit) {
    for (const m of BULK_MEDICINES) {
      if (out.length >= limit) break;
      const n = m.n.toLowerCase();
      if (!n.startsWith(q) && n.includes(q)) out.push(m);
    }
  }
  return out;
}

/** True when the name is a recognised medicine. */
export function isKnownMedicine(query: string): boolean {
  return findBulkMedicine(query) !== null;
}
